    }])
    .to_string();
    assert_eq!(project(&rows, source, &current), expected);
    assert_eq!(project(&rows, source, &expected), expected);
    for bad in [
        String::new(),
        "foreign".to_owned(),
        format!("{current} "),
        current[..current.len() - 1].to_owned(),
        format!("{expected} "),
    ] {
        assert!(std::panic::catch_unwind(|| project(&rows, source, &bad)).is_err());
    }
